INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$9debe79a$SATQ$, $SATQ$39c4e289-072b-454d-a5ae-fff58010b299$SATQ$::uuid, $SATQ$16ee60cd-0bc0-4c38-afaf-680730963f18$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Average Temperatures in July in Four Locations in the Navajo Nation</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">Location</th><th scope="col" style="text-align: center; vertical-align: bottom;">Average highest temperature (Fahrenheit)</th><th scope="col" style="text-align: center; vertical-align: bottom;">Average lowest temperature (Fahrenheit)</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">Teec Nos Pos</th><td style="text-align: center;"><span style="text-align: center;">94&deg;</span></td><td style="text-align: center;"><span style="text-align: center;">65&deg;</span></td></tr><tr><th scope="row" style="text-align: left;">Cameron</th><td style="text-align: center;"><span style="text-align: center;">99&deg;</span></td><td style="text-align: center;"><span style="text-align: center;">65&deg;</span></td></tr><tr><th scope="row" style="text-align: left;">Ramah</th><td style="text-align: center;"><span style="text-align: center;">83&deg;</span></td><td style="text-align: center;"><span style="text-align: center;">50&deg;</span></td></tr><tr><th scope="row" style="text-align: left;">Tuba City</th><td style="text-align: center;"><span style="text-align: center;">83&deg;</span></td><td style="text-align: center;"><span style="text-align: center;">50&deg;</span></td></tr></tbody></table></figure></p>
<p>The Navajo Nation has the largest land area of any tribal nation in the United States: over 27,000 square miles in the Southwest. Because this area is so huge and its communities are located at various elevations, the people of the Navajo Nation can experience different climate conditions depending on where they live. For example, in July, <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the statement?</p>$SATQ$, $SATQ$[{"id":"aed9c17c-83b3-4051-a32b-31014b6c87a8","content":"<p>the lowest temperature for both Cameron and Teec Nos Pos was 65&deg;.</p>"},{"id":"a50edeee-a2b6-4541-bfd6-cb3753cc9f4e","content":"<p>Tuba City&rsquo;s average highest temperature was 94&deg;, while Teec Nos Pos&rsquo;s was 93&deg;.</p>"},{"id":"6fac4ded-c879-4dd6-9caf-fb268c545522","content":"<p>Ramah&rsquo;s average highest temperature was 83&deg;, while Cameron&rsquo;s was 99&deg;.</p>"},{"id":"a813131a-5471-4e98-ae32-258bfc96d6b9","content":"<p>the lowest temperature for both Ramah and Tuba City was 50&deg;.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["6fac4ded-c879-4dd6-9caf-fb268c545522"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it effectively uses data from the table to complete the statement, providing an example of how the people of the Navajo Nation can experience different climate conditions depending on where they live. The table shows the average highest temperatures and average lowest temperatures in four locations in the Navajo Nation in July. According to the table, Ramah&rsquo;s average highest temperature for July was 83&deg;, whereas Cameron&rsquo;s average highest temperature was much higher, at 99&deg;. This difference illustrates the statement that the people of the Navajo Nation can experience different climate conditions depending on where they live. </p><p>Choice A is incorrect because it states that Cameron and Teec Nos Pos had the same average lowest temperature (65&deg;) for July, which suggests a similarity in climate conditions in those locations rather than a difference. Choice B is incorrect because it misrepresents the data from the table, which shows that the average highest temperature in July for Tuba City was 83&deg;, not 94&deg;, and for Teec Nos Pos it was 94&deg;, not 93&deg;. Even if the cited data accurately reflected the data in the table, the similarity between the two values for average highest temperature would suggest that people in the two locations likely experience similar climate conditions, not different climate conditions. Choice D is incorrect because it states that Ramah and Tuba City had the same average lowest temperature (50&deg;) for July, which suggests a similarity in climate conditions in those locations rather than a difference. </p>$SATQ$, false, 0, $SATQ$OSP-520-QUA$SATQ$, $SATQ$$SATQ$, $SATQ$673dc068-ac83-4bd4-bdb5-e59678ae1b62$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9debe79a","external_id":"39c4e289-072b-454d-a5ae-fff58010b299","vaultid":"16ee60cd-0bc0-4c38-afaf-680730963f18","uId":"3c65ec32-9124-43cd-a961-029425df0d3b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Average Temperatures in July in Four Locations in the Navajo Nation</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Location</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Average highest temperature (Fahrenheit)</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Average lowest temperature (Fahrenheit)</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">Teec Nos Pos</th><td style=\"text-align: center;\"><span style=\"text-align: center;\">94&deg;</span></td><td style=\"text-align: center;\"><span style=\"text-align: center;\">65&deg;</span></td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Cameron</th><td style=\"text-align: center;\"><span style=\"text-align: center;\">99&deg;</span></td><td style=\"text-align: center;\"><span style=\"text-align: center;\">65&deg;</span></td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Ramah</th><td style=\"text-align: center;\"><span style=\"text-align: center;\">83&deg;</span></td><td style=\"text-align: center;\"><span style=\"text-align: center;\">50&deg;</span></td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Tuba City</th><td style=\"text-align: center;\"><span style=\"text-align: center;\">83&deg;</span></td><td style=\"text-align: center;\"><span style=\"text-align: center;\">50&deg;</span></td></tr></tbody></table></figure></p>\n<p>The Navajo Nation has the largest land area of any tribal nation in the United States: over 27,000 square miles in the Southwest. Because this area is so huge and its communities are located at various elevations, the people of the Navajo Nation can experience different climate conditions depending on where they live. For example, in July, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the statement?</p>","answerOptions":[{"id":"aed9c17c-83b3-4051-a32b-31014b6c87a8","content":"<p>the lowest temperature for both Cameron and Teec Nos Pos was 65&deg;.</p>"},{"id":"a50edeee-a2b6-4541-bfd6-cb3753cc9f4e","content":"<p>Tuba City&rsquo;s average highest temperature was 94&deg;, while Teec Nos Pos&rsquo;s was 93&deg;.</p>"},{"id":"6fac4ded-c879-4dd6-9caf-fb268c545522","content":"<p>Ramah&rsquo;s average highest temperature was 83&deg;, while Cameron&rsquo;s was 99&deg;.</p>"},{"id":"a813131a-5471-4e98-ae32-258bfc96d6b9","content":"<p>the lowest temperature for both Ramah and Tuba City was 50&deg;.</p>"}],"keys":["6fac4ded-c879-4dd6-9caf-fb268c545522"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it effectively uses data from the table to complete the statement, providing an example of how the people of the Navajo Nation can experience different climate conditions depending on where they live. The table shows the average highest temperatures and average lowest temperatures in four locations in the Navajo Nation in July. According to the table, Ramah&rsquo;s average highest temperature for July was 83&deg;, whereas Cameron&rsquo;s average highest temperature was much higher, at 99&deg;. This difference illustrates the statement that the people of the Navajo Nation can experience different climate conditions depending on where they live. </p><p>Choice A is incorrect because it states that Cameron and Teec Nos Pos had the same average lowest temperature (65&deg;) for July, which suggests a similarity in climate conditions in those locations rather than a difference. Choice B is incorrect because it misrepresents the data from the table, which shows that the average highest temperature in July for Tuba City was 83&deg;, not 94&deg;, and for Teec Nos Pos it was 94&deg;, not 93&deg;. Even if the cited data accurately reflected the data in the table, the similarity between the two values for average highest temperature would suggest that people in the two locations likely experience similar climate conditions, not different climate conditions. Choice D is incorrect because it states that Ramah and Tuba City had the same average lowest temperature (50&deg;) for July, which suggests a similarity in climate conditions in those locations rather than a difference. </p>","parenttemplatename":"OSP-520-QUA","parenttemplateid":"","templateclusterid":"673dc068-ac83-4bd4-bdb5-e59678ae1b62","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959337,"updateDate":1691007959337}$SATQ$::jsonb, 1691007959337, 1691007959337),
    ($SATQ$9e5ce27c$SATQ$, $SATQ$ed118154-f369-47fe-850a-70e12f3794d8$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;Lines Written in Early Spring&rdquo; is a 1798 poem by William Wordsworth. In the poem, the speaker describes having contradictory feelings while experiencing the sights and sounds of a spring day: <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from &ldquo;Lines Written in Early Spring&rdquo; most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"ee2ea2b7-8f70-46ed-a560-1e9bc7a3878c","content":"<p>&ldquo;Through primrose-tufts, in that sweet bower, / The periwinkle trail&rsquo;d its wreathes; / And &rsquo;tis my faith that every flower / Enjoys the air it breathes.&rdquo;</p>"},{"id":"0ccbf86d-2ddf-48d8-a2ce-91dd97f05147","content":"<p>&ldquo;The budding twigs spread out their fan, / To catch the breezy air; / And I must think, do all I can, / That there was pleasure there.&rdquo;</p>"},{"id":"8f888d64-7cc4-41fb-8fbd-d739ca6f657c","content":"<p>&ldquo;The birds around me hopp&rsquo;d and play&rsquo;d: / Their thoughts I cannot measure, / But the least motion which they made, / It seem&rsquo;d a thrill of pleasure.&rdquo;</p>"},{"id":"5ac559be-8f31-4b24-8d5c-654876283edd","content":"<p>&ldquo;I heard a thousand blended notes, / While in a grove I [sat] reclined, / In that sweet mood when pleasant thoughts / Bring sad thoughts to the mind.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["5ac559be-8f31-4b24-8d5c-654876283edd"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most effectively illustrates the claim that the speaker has contradictory feelings while experiencing the sights and sounds of spring. This quotation indicates that the speaker is reclined in a grove listening to a thousand sounds. Even though the speaker is in a "sweet mood" and thinking "pleasant thoughts," those pleasant thoughts also bring to mind "sad thoughts." In other words, these lines illustrate the claim that the speaker is having contradictory thoughts while immersed in the sights and sounds of spring.</p><p>Choice A is incorrect. Although this quotation refers to several flowers (primroses and periwinkles) and indicates that the speaker is in a "bower," or shady spot among the trees&mdash;details which suggest that the speaker is experiencing the sights of spring&mdash;it doesn&rsquo;t suggest that the speaker is having contradictory feelings, only that the speaker believes that the flowers are experiencing enjoyment. Choice B is incorrect. Although this quotation focuses on the sights of spring&mdash;namely, new leaves on nearby trees appear to be opening up ("The budding twigs spread out their fan") to feel the breeze&mdash;the quotation doesn&rsquo;t suggest that the speaker feels conflicted about this: the statement "And I must think, do all I can" suggests the speaker&rsquo;s determination to attribute feelings of pleasure to the trees, not that the speaker is experiencing contradictory feelings. Choice C is incorrect. Although this quotation indicates that the speaker isn&rsquo;t certain what the birds are thinking ("Their thoughts I cannot measure"), there&rsquo;s nothing to suggest that the speaker is experiencing contradictory feelings. Rather, the quotation suggests that although the speaker is uncertain about the birds&rsquo; feelings, the speaker believes that the birds&rsquo; movements likely suggest their pleasure.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"9e5ce27c","external_id":"ed118154-f369-47fe-850a-70e12f3794d8","vaultid":null,"uId":"7862a971-f057-4381-8bca-c3db30c27831","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>&ldquo;Lines Written in Early Spring&rdquo; is a 1798 poem by William Wordsworth. In the poem, the speaker describes having contradictory feelings while experiencing the sights and sounds of a spring day: <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from &ldquo;Lines Written in Early Spring&rdquo; most effectively illustrates the claim?</p>","answerOptions":[{"id":"ee2ea2b7-8f70-46ed-a560-1e9bc7a3878c","content":"<p>&ldquo;Through primrose-tufts, in that sweet bower, / The periwinkle trail&rsquo;d its wreathes; / And &rsquo;tis my faith that every flower / Enjoys the air it breathes.&rdquo;</p>"},{"id":"0ccbf86d-2ddf-48d8-a2ce-91dd97f05147","content":"<p>&ldquo;The budding twigs spread out their fan, / To catch the breezy air; / And I must think, do all I can, / That there was pleasure there.&rdquo;</p>"},{"id":"8f888d64-7cc4-41fb-8fbd-d739ca6f657c","content":"<p>&ldquo;The birds around me hopp&rsquo;d and play&rsquo;d: / Their thoughts I cannot measure, / But the least motion which they made, / It seem&rsquo;d a thrill of pleasure.&rdquo;</p>"},{"id":"5ac559be-8f31-4b24-8d5c-654876283edd","content":"<p>&ldquo;I heard a thousand blended notes, / While in a grove I [sat] reclined, / In that sweet mood when pleasant thoughts / Bring sad thoughts to the mind.&rdquo;</p>"}],"keys":["5ac559be-8f31-4b24-8d5c-654876283edd"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most effectively illustrates the claim that the speaker has contradictory feelings while experiencing the sights and sounds of spring. This quotation indicates that the speaker is reclined in a grove listening to a thousand sounds. Even though the speaker is in a \"sweet mood\" and thinking \"pleasant thoughts,\" those pleasant thoughts also bring to mind \"sad thoughts.\" In other words, these lines illustrate the claim that the speaker is having contradictory thoughts while immersed in the sights and sounds of spring.</p><p>Choice A is incorrect. Although this quotation refers to several flowers (primroses and periwinkles) and indicates that the speaker is in a \"bower,\" or shady spot among the trees&mdash;details which suggest that the speaker is experiencing the sights of spring&mdash;it doesn&rsquo;t suggest that the speaker is having contradictory feelings, only that the speaker believes that the flowers are experiencing enjoyment. Choice B is incorrect. Although this quotation focuses on the sights of spring&mdash;namely, new leaves on nearby trees appear to be opening up (\"The budding twigs spread out their fan\") to feel the breeze&mdash;the quotation doesn&rsquo;t suggest that the speaker feels conflicted about this: the statement \"And I must think, do all I can\" suggests the speaker&rsquo;s determination to attribute feelings of pleasure to the trees, not that the speaker is experiencing contradictory feelings. Choice C is incorrect. Although this quotation indicates that the speaker isn&rsquo;t certain what the birds are thinking (\"Their thoughts I cannot measure\"), there&rsquo;s nothing to suggest that the speaker is experiencing contradictory feelings. Rather, the quotation suggests that although the speaker is uncertain about the birds&rsquo; feelings, the speaker believes that the birds&rsquo; movements likely suggest their pleasure.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323044,"updateDate":1730147323044}$SATQ$::jsonb, 1730147323044, 1730147323044),
    ($SATQ$9fe7aafa$SATQ$, $SATQ$fbf6b996-3607-41ed-a39c-163d8c8c394c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The ancient writing system used in the Maya kingdoms of southern Mexico and Central America had a symbol for the number zero. The earliest known example of the symbol dates to more than 2,000 years ago. At that time, almost none of the writing systems elsewhere in the world possessed a zero symbol. And the use of zero in Mexico and Central America may be even more ancient. Some historians suggest that Maya mathematicians inherited it from the Olmec civilization, which flourished in the region 2,400&ndash;3,600 years ago.</p>$SATQ$, $SATQ$<p>According to the text, what do some historians suggest about Maya civilization?</p>$SATQ$, $SATQ$[{"id":"73e364b8-e2d4-49f6-869c-5eb42b27c082","content":"<p>Maya civilization acquired the use of zero from the Olmec civilization.</p>"},{"id":"1fdca963-58de-4f36-9a2b-113da146ad37","content":"<p>Maya civilization respected its historians more than it respected its mathematicians.</p>"},{"id":"d3bd76fb-c32d-4a24-b4cd-908d9dbca175","content":"<p>Maya civilization was highly secretive about its intellectual achievements.</p>"},{"id":"d7ff095c-5a7d-4038-b4a9-9119eee3889c","content":"<p>Maya civilization tried to introduce its writing system to other civilizations.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["73e364b8-e2d4-49f6-869c-5eb42b27c082"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents information about Maya civilization that is supported by the text. The text states that the writing system used in the Maya kingdoms had a symbol for the number zero. It goes on to say that at the time of the zero symbol&rsquo;s earliest example, more than 2,000 years ago, almost no other writing systems in the world featured such a symbol. The text also points out that some historians suggest that Maya mathematicians inherited the use of zero from the Olmec civilization, which existed in the same area as the Maya civilization at an earlier date. Thus, according to the text, some historians suggest that the Maya civilization acquired the use of zero from the Olmec civilization.</p><p>Choice B is incorrect because although the text mentions present-day historians and Maya mathematicians, it does not say anything about how much the Maya civilization respected its historians and mathematicians. Choice C is incorrect because the text does not indicate that the Maya civilization treated its use of the zero symbol, or any other intellectual achievements, as secrets to be kept from other civilizations. Choice D is incorrect because although the text mentions historians who suggest that the writing system of the Maya civilization inherited some features from the earlier Olmec civilization, the text does not describe any attempts of Maya civilization to introduce its writing system to other civilizations.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"9fe7aafa","external_id":"fbf6b996-3607-41ed-a39c-163d8c8c394c","vaultid":null,"uId":"593d9904-c3c9-4099-8a9c-1a7e021464a9","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The ancient writing system used in the Maya kingdoms of southern Mexico and Central America had a symbol for the number zero. The earliest known example of the symbol dates to more than 2,000 years ago. At that time, almost none of the writing systems elsewhere in the world possessed a zero symbol. And the use of zero in Mexico and Central America may be even more ancient. Some historians suggest that Maya mathematicians inherited it from the Olmec civilization, which flourished in the region 2,400&ndash;3,600 years ago.</p>","stem":"<p>According to the text, what do some historians suggest about Maya civilization?</p>","answerOptions":[{"id":"73e364b8-e2d4-49f6-869c-5eb42b27c082","content":"<p>Maya civilization acquired the use of zero from the Olmec civilization.</p>"},{"id":"1fdca963-58de-4f36-9a2b-113da146ad37","content":"<p>Maya civilization respected its historians more than it respected its mathematicians.</p>"},{"id":"d3bd76fb-c32d-4a24-b4cd-908d9dbca175","content":"<p>Maya civilization was highly secretive about its intellectual achievements.</p>"},{"id":"d7ff095c-5a7d-4038-b4a9-9119eee3889c","content":"<p>Maya civilization tried to introduce its writing system to other civilizations.</p>"}],"keys":["73e364b8-e2d4-49f6-869c-5eb42b27c082"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents information about Maya civilization that is supported by the text. The text states that the writing system used in the Maya kingdoms had a symbol for the number zero. It goes on to say that at the time of the zero symbol&rsquo;s earliest example, more than 2,000 years ago, almost no other writing systems in the world featured such a symbol. The text also points out that some historians suggest that Maya mathematicians inherited the use of zero from the Olmec civilization, which existed in the same area as the Maya civilization at an earlier date. Thus, according to the text, some historians suggest that the Maya civilization acquired the use of zero from the Olmec civilization.</p><p>Choice B is incorrect because although the text mentions present-day historians and Maya mathematicians, it does not say anything about how much the Maya civilization respected its historians and mathematicians. Choice C is incorrect because the text does not indicate that the Maya civilization treated its use of the zero symbol, or any other intellectual achievements, as secrets to be kept from other civilizations. Choice D is incorrect because although the text mentions historians who suggest that the writing system of the Maya civilization inherited some features from the earlier Olmec civilization, the text does not describe any attempts of Maya civilization to introduce its writing system to other civilizations.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323035,"updateDate":1730147323035}$SATQ$::jsonb, 1730147323035, 1730147323035),
    ($SATQ$a0203977$SATQ$, $SATQ$f18119e1-0678-452f-bee5-0dfaddbe173f$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Annual Spending by International Tourists in Four Countries (in billions of US dollars)</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Country</th><th scope="col" style="text-align: center;vertical-align: bottom;">2016</th><th scope="col" style="text-align: center;vertical-align: bottom;">2017</th><th scope="col" style="text-align: center;vertical-align: bottom;">2018</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">South Korea</th><td style="text-align: center;">$21.0</td><td style="text-align: center;">$17.2</td><td style="text-align: center;">$23.1</td></tr><tr><th scope="row" style="text-align: left;">Japan</th><td style="text-align: center;">$33.5</td><td style="text-align: center;">$37.0</td><td style="text-align: center;">$45.3</td></tr><tr><th scope="row" style="text-align: left;">Thailand</th><td style="text-align: center;">$48.5</td><td style="text-align: center;">$57.1</td><td style="text-align: center;">$61.4</td></tr><tr><th scope="row" style="text-align: left;">Malaysia</th><td style="text-align: center;">$19.7</td><td style="text-align: center;">$20.3</td><td style="text-align: center;">$21.8</td></tr></tbody></table></figure></p>
<p>One measure of international tourism is how much money visitors from abroad spend in a country. A student writing a report about tourism in several Asian countries notes that among the countries in the table, most had annual increases in international tourism revenue in 2017 and 2018, but that trend wasn&rsquo;t universal. For example, <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the example?</p>$SATQ$, $SATQ$[{"id":"acd21bdb-9750-4a16-94b4-ed99b3785cd3","content":"<p>in each year shown, the revenue from tourism by residents of those countries was greater than the revenue from international tourism.</p>"},{"id":"1a40b58c-0e42-4df7-8d97-b73a547a6bdf","content":"<p>Japan&rsquo;s international tourism revenue was higher in 2016 than it was in 2018.</p>"},{"id":"c6ac3c40-3632-445f-8e49-7692dee9d76e","content":"<p>South Korea&rsquo;s annual international tourism revenue decreased from 2016 to 2017.</p>"},{"id":"aab527d6-b50c-499c-b206-877172ca4085","content":"<p>in each year shown, Thailand had higher international tourism income than any of the other countries.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["c6ac3c40-3632-445f-8e49-7692dee9d76e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most effectively uses data from the table to complete the text, providing an example that illustrates that the annual increases in international tourism revenue in 2017 and 2018 weren&rsquo;t universal. The table shows the annual spending by international tourists (which indicates annual international tourism revenue) in 2016&ndash;2018 in four Asian countries. According to the table, annual spending by international tourists in South Korea was $21.0 billion in 2016 and then decreased to $17.2 billion in 2017. This decrease shows that not all of the countries included in the table saw increases in annual international tourism revenue in 2017.</p><p>Choice A is incorrect because the table doesn&rsquo;t provide any data regarding revenue from tourism by residents of those countries. Even if that data were provided, it wouldn&rsquo;t be relevant to the claim that the trend of annual increases in international tourism revenue in 2017 and 2018 was not universal. Choice B is incorrect because the data in the table do not support the statement that Japan&rsquo;s international tourism revenue was higher in 2016 than it was in 2018: the table indicates that Japan&rsquo;s annual international tourism revenue was $33.5 billion in 2016, which is less than Japan&rsquo;s annual international tourism revenue of $45.3 billion in 2018. Choice D is incorrect. Although the table does indicate that Thailand&rsquo;s revenue from international tourism was higher than that of the other three Asian countries in 2016, 2017, and 2018, this information has no direct bearing on the text&rsquo;s claim that not all the Asian countries represented in the table saw an increase in revenue from international tourism.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a0203977","external_id":"f18119e1-0678-452f-bee5-0dfaddbe173f","vaultid":null,"uId":"8dd37d5e-eae3-4d31-a8ba-e62e8698f21d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Annual Spending by International Tourists in Four Countries (in billions of US dollars)</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Country</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">2016</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">2017</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">2018</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">South Korea</th><td style=\"text-align: center;\">$21.0</td><td style=\"text-align: center;\">$17.2</td><td style=\"text-align: center;\">$23.1</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Japan</th><td style=\"text-align: center;\">$33.5</td><td style=\"text-align: center;\">$37.0</td><td style=\"text-align: center;\">$45.3</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Thailand</th><td style=\"text-align: center;\">$48.5</td><td style=\"text-align: center;\">$57.1</td><td style=\"text-align: center;\">$61.4</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Malaysia</th><td style=\"text-align: center;\">$19.7</td><td style=\"text-align: center;\">$20.3</td><td style=\"text-align: center;\">$21.8</td></tr></tbody></table></figure></p>\n<p>One measure of international tourism is how much money visitors from abroad spend in a country. A student writing a report about tourism in several Asian countries notes that among the countries in the table, most had annual increases in international tourism revenue in 2017 and 2018, but that trend wasn&rsquo;t universal. For example, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the example?</p>","answerOptions":[{"id":"acd21bdb-9750-4a16-94b4-ed99b3785cd3","content":"<p>in each year shown, the revenue from tourism by residents of those countries was greater than the revenue from international tourism.</p>"},{"id":"1a40b58c-0e42-4df7-8d97-b73a547a6bdf","content":"<p>Japan&rsquo;s international tourism revenue was higher in 2016 than it was in 2018.</p>"},{"id":"c6ac3c40-3632-445f-8e49-7692dee9d76e","content":"<p>South Korea&rsquo;s annual international tourism revenue decreased from 2016 to 2017.</p>"},{"id":"aab527d6-b50c-499c-b206-877172ca4085","content":"<p>in each year shown, Thailand had higher international tourism income than any of the other countries.</p>"}],"keys":["c6ac3c40-3632-445f-8e49-7692dee9d76e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most effectively uses data from the table to complete the text, providing an example that illustrates that the annual increases in international tourism revenue in 2017 and 2018 weren&rsquo;t universal. The table shows the annual spending by international tourists (which indicates annual international tourism revenue) in 2016&ndash;2018 in four Asian countries. According to the table, annual spending by international tourists in South Korea was $21.0 billion in 2016 and then decreased to $17.2 billion in 2017. This decrease shows that not all of the countries included in the table saw increases in annual international tourism revenue in 2017.</p><p>Choice A is incorrect because the table doesn&rsquo;t provide any data regarding revenue from tourism by residents of those countries. Even if that data were provided, it wouldn&rsquo;t be relevant to the claim that the trend of annual increases in international tourism revenue in 2017 and 2018 was not universal. Choice B is incorrect because the data in the table do not support the statement that Japan&rsquo;s international tourism revenue was higher in 2016 than it was in 2018: the table indicates that Japan&rsquo;s annual international tourism revenue was $33.5 billion in 2016, which is less than Japan&rsquo;s annual international tourism revenue of $45.3 billion in 2018. Choice D is incorrect. Although the table does indicate that Thailand&rsquo;s revenue from international tourism was higher than that of the other three Asian countries in 2016, 2017, and 2018, this information has no direct bearing on the text&rsquo;s claim that not all the Asian countries represented in the table saw an increase in revenue from international tourism.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323046,"updateDate":1730147323046}$SATQ$::jsonb, 1730147323046, 1730147323046),
    ($SATQ$a04807d8$SATQ$, $SATQ$6096b294-0cc7-4495-a3a6-0e0db167e92c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Number of Museum Visits (in Millions) from 2016 to 2019</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Museum</th><th scope="col" style="text-align: center;vertical-align: bottom;">2016</th><th scope="col" style="text-align: center;vertical-align: bottom;">2017</th><th scope="col" style="text-align: center;vertical-align: bottom;">2018</th><th scope="col" style="text-align: center;vertical-align: bottom;">2019</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">National Museum of the American Indian</th><td style="text-align: center;">1.1</td><td style="text-align: center;">1.2</td><td style="text-align: center;">1.1</td><td style="text-align: center;">0.96</td></tr><tr><th scope="row" style="text-align: left;">National Museum of African American History and Culture</th><td style="text-align: center;">0.73</td><td style="text-align: center;">2.4</td><td style="text-align: center;">1.9</td><td style="text-align: center;">2.0</td></tr></tbody></table></figure></p>
<p>A student is researching the number of visits each year to two museums, the National Museum of the American Indian and the National Museum of African American History and Culture. Of the four years included in the table, the year when both museums had the highest number of visits was <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the statement?</p>$SATQ$, $SATQ$[{"id":"57bc07d4-efdc-4ffc-8c8f-0aa715256289","content":"<p>2016.</p>"},{"id":"9ecfc300-47c1-467c-8e07-7264449d66fb","content":"<p>2018.</p>"},{"id":"227aff62-7634-4ffb-a0e2-5167d0608c61","content":"<p>2019.</p>"},{"id":"dc5e3df3-af26-41cd-9301-0e23b923181d","content":"<p>2017.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["dc5e3df3-af26-41cd-9301-0e23b923181d"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most effectively uses data from the table to complete the statement about the year when both museums had the highest number of visits. The table shows the number of visits (in millions) from 2016 to 2019 to two museums: the National Museum of the American Indian and the National Museum of African American History and Culture. It indicates that the highest number of visits to the National Museum of the American Indian was 1.2 million in 2017 and that the highest number of visits to the National Museum of African American History and Culture was 2.4 million, also in 2017.</p><p>Choice A is incorrect because the table shows that in 2016, the National Museum of the American Indian had 1.1 million visits and that the National Museum of African American History and Culture had 0.73 million visits, both of which are lower than the number of visits these museums had in 2017. Choice B is incorrect because the table shows that in 2018, the National Museum of the American Indian had 1.1 million visits and that the National Museum of African American History and Culture had 1.9 million visits, both of which are lower than the number of visits these museums had in 2017. Choice C is incorrect because the table shows that in 2019, the National Museum of the American Indian had 0.96 million visits and that the National Museum of African American History and Culture had 2.0 million visits, both of which are lower than the number of visits these museums had in 2017.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a04807d8","external_id":"6096b294-0cc7-4495-a3a6-0e0db167e92c","vaultid":null,"uId":"8dcbf336-6f3f-4e81-9703-d7190880db4e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Number of Museum Visits (in Millions) from 2016 to 2019</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Museum</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">2016</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">2017</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">2018</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">2019</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">National Museum of the American Indian</th><td style=\"text-align: center;\">1.1</td><td style=\"text-align: center;\">1.2</td><td style=\"text-align: center;\">1.1</td><td style=\"text-align: center;\">0.96</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">National Museum of African American History and Culture</th><td style=\"text-align: center;\">0.73</td><td style=\"text-align: center;\">2.4</td><td style=\"text-align: center;\">1.9</td><td style=\"text-align: center;\">2.0</td></tr></tbody></table></figure></p>\n<p>A student is researching the number of visits each year to two museums, the National Museum of the American Indian and the National Museum of African American History and Culture. Of the four years included in the table, the year when both museums had the highest number of visits was <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the statement?</p>","answerOptions":[{"id":"57bc07d4-efdc-4ffc-8c8f-0aa715256289","content":"<p>2016.</p>"},{"id":"9ecfc300-47c1-467c-8e07-7264449d66fb","content":"<p>2018.</p>"},{"id":"227aff62-7634-4ffb-a0e2-5167d0608c61","content":"<p>2019.</p>"},{"id":"dc5e3df3-af26-41cd-9301-0e23b923181d","content":"<p>2017.</p>"}],"keys":["dc5e3df3-af26-41cd-9301-0e23b923181d"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most effectively uses data from the table to complete the statement about the year when both museums had the highest number of visits. The table shows the number of visits (in millions) from 2016 to 2019 to two museums: the National Museum of the American Indian and the National Museum of African American History and Culture. It indicates that the highest number of visits to the National Museum of the American Indian was 1.2 million in 2017 and that the highest number of visits to the National Museum of African American History and Culture was 2.4 million, also in 2017.</p><p>Choice A is incorrect because the table shows that in 2016, the National Museum of the American Indian had 1.1 million visits and that the National Museum of African American History and Culture had 0.73 million visits, both of which are lower than the number of visits these museums had in 2017. Choice B is incorrect because the table shows that in 2018, the National Museum of the American Indian had 1.1 million visits and that the National Museum of African American History and Culture had 1.9 million visits, both of which are lower than the number of visits these museums had in 2017. Choice C is incorrect because the table shows that in 2019, the National Museum of the American Indian had 0.96 million visits and that the National Museum of African American History and Culture had 2.0 million visits, both of which are lower than the number of visits these museums had in 2017.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323046,"updateDate":1730147323046}$SATQ$::jsonb, 1730147323046, 1730147323046),
    ($SATQ$a0b58ef0$SATQ$, $SATQ$1ed4ac27-d126-4d76-bede-761cd94cd8c9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The Younger Dryas was a period of extreme cooling from 11,700 to 12,900 years ago in the Northern Hemisphere. Some scientists argue that a comet fragment hitting Earth brought about the cooling. Others disagree, partly because there is no known crater from such an impact that dates to the beginning of the period. In 2015, a team led by Kurt Kj&aelig;r detected a 19-mile-wide crater beneath a glacier in Greenland. The scientists who believe an impact caused the Younger Dryas claim that this discovery supports their view. However, Kj&aelig;r&rsquo;s team hasn&rsquo;t yet been able to determine the age of the crater. Therefore, the team suggests that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"285ab51d-b2d8-45c0-a4d1-328b8e29b197","content":"<p>it can&rsquo;t be concluded that the impact that made the crater was connected to the beginning of the Younger Dryas.</p>"},{"id":"578f1141-64a8-4a63-bcb1-2ee7a8d220a5","content":"<p>it can&rsquo;t be determined whether a comet fragment could make a crater as large as 19 miles wide.</p>"},{"id":"0e37a9b3-3353-4221-a4a4-5c142dea635e","content":"<p>scientists have ignored the possibility that something other than a comet fragment could have made the crater.</p>"},{"id":"e7282342-0fb7-4c5c-be26-5d4497484adf","content":"<p>the scientists who believe an impact caused the Younger Dryas have made incorrect assumptions about when the period began.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["285ab51d-b2d8-45c0-a4d1-328b8e29b197"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of a crater&rsquo;s connection to the start of the Younger Dryas. According to the text, some scientists believe that a comet fragment hitting Earth caused the cooling of the Younger Dryas period to come about. The text then indicates that a team of scientists found a crater in Greenland, which some believe supports the theory of a comet fragment hitting Earth to initiate the Younger Dryas. However, the text also notes that the team was unable to determine the age of the crater. If the age of the crater can&rsquo;t be determined, then its connection to the Younger Dryas period of time can&rsquo;t be confirmed either. Thus, it can&rsquo;t be concluded that the impact that made the crater was connected to the beginning of the Younger Dryas.</p><p>Choice B is incorrect because though the text suggests that the age of the comet crater found by a team of scientists is uncertain, it doesn&rsquo;t address whether a comet fragment can make a crater as large as 19 miles wide. The text doesn&rsquo;t consider the size of comet fragments and how they relate to the size of craters they might make. Choice C is incorrect because the debate in the text centers on the age of the crater found, not the cause of the crater. The text doesn&rsquo;t indicate uncertainty about what caused the discovered crater. Choice D is incorrect because the text suggests that the age of the crater found by the team of scientists is uncertain, not that the dates of the Younger Dryas are uncertain or incorrect. The text states that "the Younger Dryas was a period of extreme cooling from 11,700 to 12,900 years ago" but doesn&rsquo;t indicate any debate about the timing of the period.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a0b58ef0","external_id":"1ed4ac27-d126-4d76-bede-761cd94cd8c9","vaultid":null,"uId":"b5f57c96-7e47-4647-820a-6112fbe3d4b2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The Younger Dryas was a period of extreme cooling from 11,700 to 12,900 years ago in the Northern Hemisphere. Some scientists argue that a comet fragment hitting Earth brought about the cooling. Others disagree, partly because there is no known crater from such an impact that dates to the beginning of the period. In 2015, a team led by Kurt Kj&aelig;r detected a 19-mile-wide crater beneath a glacier in Greenland. The scientists who believe an impact caused the Younger Dryas claim that this discovery supports their view. However, Kj&aelig;r&rsquo;s team hasn&rsquo;t yet been able to determine the age of the crater. Therefore, the team suggests that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"285ab51d-b2d8-45c0-a4d1-328b8e29b197","content":"<p>it can&rsquo;t be concluded that the impact that made the crater was connected to the beginning of the Younger Dryas.</p>"},{"id":"578f1141-64a8-4a63-bcb1-2ee7a8d220a5","content":"<p>it can&rsquo;t be determined whether a comet fragment could make a crater as large as 19 miles wide.</p>"},{"id":"0e37a9b3-3353-4221-a4a4-5c142dea635e","content":"<p>scientists have ignored the possibility that something other than a comet fragment could have made the crater.</p>"},{"id":"e7282342-0fb7-4c5c-be26-5d4497484adf","content":"<p>the scientists who believe an impact caused the Younger Dryas have made incorrect assumptions about when the period began.</p>"}],"keys":["285ab51d-b2d8-45c0-a4d1-328b8e29b197"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of a crater&rsquo;s connection to the start of the Younger Dryas. According to the text, some scientists believe that a comet fragment hitting Earth caused the cooling of the Younger Dryas period to come about. The text then indicates that a team of scientists found a crater in Greenland, which some believe supports the theory of a comet fragment hitting Earth to initiate the Younger Dryas. However, the text also notes that the team was unable to determine the age of the crater. If the age of the crater can&rsquo;t be determined, then its connection to the Younger Dryas period of time can&rsquo;t be confirmed either. Thus, it can&rsquo;t be concluded that the impact that made the crater was connected to the beginning of the Younger Dryas.</p><p>Choice B is incorrect because though the text suggests that the age of the comet crater found by a team of scientists is uncertain, it doesn&rsquo;t address whether a comet fragment can make a crater as large as 19 miles wide. The text doesn&rsquo;t consider the size of comet fragments and how they relate to the size of craters they might make. Choice C is incorrect because the debate in the text centers on the age of the crater found, not the cause of the crater. The text doesn&rsquo;t indicate uncertainty about what caused the discovered crater. Choice D is incorrect because the text suggests that the age of the crater found by the team of scientists is uncertain, not that the dates of the Younger Dryas are uncertain or incorrect. The text states that \"the Younger Dryas was a period of extreme cooling from 11,700 to 12,900 years ago\" but doesn&rsquo;t indicate any debate about the timing of the period.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323035,"updateDate":1730147323035}$SATQ$::jsonb, 1730147323035, 1730147323035),
    ($SATQ$a12a83ce$SATQ$, $SATQ$55520f1a-8cea-4e4d-a5e4-12e755466da1$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from William Shakespeare&rsquo;s play <em>The Tempest</em>, first performed in 1611. Miranda has lived on an island with her father, Prospero, since she was three years old. Prospero has stated that Miranda likely does not remember anything other than her life on the island.</p>
<blockquote>
<p>MIRANDA: &rsquo;Tis far off,</p>
<p>And rather like a dream than an assurance</p>
<p>That my remembrance warrants. Had I not</p>
<p>Four or five women once that tended me?</p>
<p>&nbsp;</p>
<p>PROSPERO: Thou hadst, and more, Miranda. But how is it</p>
<p>That this lives in thy mind? What seest thou else</p>
<p>In the dark backward and abysm of time?</p>
<p>If thou remember&rsquo;st ought ere thou camest here,</p>
<p>How thou camest here thou mayst.</p>
</blockquote>$SATQ$, $SATQ$<p>In the text, which point does Prospero most directly make about Miranda and her memories?</p>$SATQ$, $SATQ$[{"id":"85487af3-1b14-4b42-a7a1-24e6acf94388","content":"<p>Miranda&rsquo;s reminiscences about her early childhood have a melancholy quality that betrays her discontented view of her current circumstances.</p>"},{"id":"ed1d40ac-ac11-4456-b54b-c100c0dbf93c","content":"<p>Miranda&rsquo;s doubts about the accuracy of one recollection of a place other than the island are clouding her judgment and seem to be making her reluctant to explore her recollection of traveling to the island.</p>"},{"id":"cc80656d-61f2-48e7-9ff6-7ef7948573a8","content":"<p>Miranda&rsquo;s ability to summon details of an experience she had before arriving on the island suggests that she may also be able to summon details of her arrival on the island.</p>"},{"id":"da56863c-9d53-4853-b317-8c271f7c034b","content":"<p>Miranda&rsquo;s impression of a scene is vague because she is remembering a scenario she had daydreamed about as a child rather than a scenario that had occurred in reality.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["cc80656d-61f2-48e7-9ff6-7ef7948573a8"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it presents a point that Prospero makes about Miranda. The text begins with Miranda responding to Prospero&rsquo;s claim that she probably doesn&rsquo;t remember her life before the island. She describes a distant memory, asking if she had "four or five women" caring for her. Prospero confirms this ("thou hadst") and then asks what else she can recall, stating that because she remembers one thing from the time before she lived on the island ("ought ere thou camest here"), she might also remember arriving on the island ("how thou camest here"). That is, Prospero indicates that Miranda&rsquo;s ability to summon details of an experience from before her arrival on the island suggests that she may also be able to summon details of her arrival.</p><p>Choice A is incorrect because Prospero doesn&rsquo;t say anything about how Miranda presents her early childhood memory of having several people care for her&mdash;he indicates only his surprise that she remembers something from so long ago ("the dark backward and abysm of time") and his thought that she may also be able to recall another childhood event: her arrival on the island. Further, Prospero doesn&rsquo;t suggest that he believes Miranda is discontent in her current circumstances. Choice B is incorrect. Although Miranda suggests some doubt about her recollection of a place other than the island, in that she describes it as "like a dream" she can&rsquo;t be certain of, Prospero doesn&rsquo;t mention her uncertainty&mdash;though he himself wonders how it is possible that she correctly recalls something from so long ago ("abysm of time"). Rather than indicating that doubt is making Miranda reluctant, Prospero simply states that Miranda may have the ability to remember traveling to the island. Choice D is incorrect. Although Miranda describes a vague impression of several people who cared for her as a young child and states that it is "rather like a dream" instead of something she is certain is real, Prospero doesn&rsquo;t indicate that Miranda is remembering a childhood daydream. Instead, he confirms that what Miranda remembers actually happened, answering her question about having had caregivers with "thou hadst," and asks her what else she can remember from long ago.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a12a83ce","external_id":"55520f1a-8cea-4e4d-a5e4-12e755466da1","vaultid":null,"uId":"beeb8c7b-38a6-462e-8c29-1b5d4c89d078","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The following text is from William Shakespeare&rsquo;s play <em>The Tempest</em>, first performed in 1611. Miranda has lived on an island with her father, Prospero, since she was three years old. Prospero has stated that Miranda likely does not remember anything other than her life on the island.</p>\n<blockquote>\n<p>MIRANDA: &rsquo;Tis far off,</p>\n<p>And rather like a dream than an assurance</p>\n<p>That my remembrance warrants. Had I not</p>\n<p>Four or five women once that tended me?</p>\n<p>&nbsp;</p>\n<p>PROSPERO: Thou hadst, and more, Miranda. But how is it</p>\n<p>That this lives in thy mind? What seest thou else</p>\n<p>In the dark backward and abysm of time?</p>\n<p>If thou remember&rsquo;st ought ere thou camest here,</p>\n<p>How thou camest here thou mayst.</p>\n</blockquote>","stem":"<p>In the text, which point does Prospero most directly make about Miranda and her memories?</p>","answerOptions":[{"id":"85487af3-1b14-4b42-a7a1-24e6acf94388","content":"<p>Miranda&rsquo;s reminiscences about her early childhood have a melancholy quality that betrays her discontented view of her current circumstances.</p>"},{"id":"ed1d40ac-ac11-4456-b54b-c100c0dbf93c","content":"<p>Miranda&rsquo;s doubts about the accuracy of one recollection of a place other than the island are clouding her judgment and seem to be making her reluctant to explore her recollection of traveling to the island.</p>"},{"id":"cc80656d-61f2-48e7-9ff6-7ef7948573a8","content":"<p>Miranda&rsquo;s ability to summon details of an experience she had before arriving on the island suggests that she may also be able to summon details of her arrival on the island.</p>"},{"id":"da56863c-9d53-4853-b317-8c271f7c034b","content":"<p>Miranda&rsquo;s impression of a scene is vague because she is remembering a scenario she had daydreamed about as a child rather than a scenario that had occurred in reality.</p>"}],"keys":["cc80656d-61f2-48e7-9ff6-7ef7948573a8"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it presents a point that Prospero makes about Miranda. The text begins with Miranda responding to Prospero&rsquo;s claim that she probably doesn&rsquo;t remember her life before the island. She describes a distant memory, asking if she had \"four or five women\" caring for her. Prospero confirms this (\"thou hadst\") and then asks what else she can recall, stating that because she remembers one thing from the time before she lived on the island (\"ought ere thou camest here\"), she might also remember arriving on the island (\"how thou camest here\"). That is, Prospero indicates that Miranda&rsquo;s ability to summon details of an experience from before her arrival on the island suggests that she may also be able to summon details of her arrival.</p><p>Choice A is incorrect because Prospero doesn&rsquo;t say anything about how Miranda presents her early childhood memory of having several people care for her&mdash;he indicates only his surprise that she remembers something from so long ago (\"the dark backward and abysm of time\") and his thought that she may also be able to recall another childhood event: her arrival on the island. Further, Prospero doesn&rsquo;t suggest that he believes Miranda is discontent in her current circumstances. Choice B is incorrect. Although Miranda suggests some doubt about her recollection of a place other than the island, in that she describes it as \"like a dream\" she can&rsquo;t be certain of, Prospero doesn&rsquo;t mention her uncertainty&mdash;though he himself wonders how it is possible that she correctly recalls something from so long ago (\"abysm of time\"). Rather than indicating that doubt is making Miranda reluctant, Prospero simply states that Miranda may have the ability to remember traveling to the island. Choice D is incorrect. Although Miranda describes a vague impression of several people who cared for her as a young child and states that it is \"rather like a dream\" instead of something she is certain is real, Prospero doesn&rsquo;t indicate that Miranda is remembering a childhood daydream. Instead, he confirms that what Miranda remembers actually happened, answering her question about having had caregivers with \"thou hadst,\" and asks her what else she can remember from long ago.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669207,"updateDate":1743430669207}$SATQ$::jsonb, 1743430669207, 1743430669207),
    ($SATQ$a13541c0$SATQ$, $SATQ$130d0a84-b1b0-4f4b-9201-cd5cc26e4514$SATQ$::uuid, $SATQ$832c7c33-4d29-4b2c-b707-09ead941d39e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Sandra Cisneros&rsquo;s 1984 novella <em>The House on Mango Street</em> made a lasting impact on US literature. Its depiction of Mexican American culture inspired later authors to examine their own heritage within their fictional works. Also influential was the book&rsquo;s portrayal of the main character, Esperanza, during a pivotal year of her youth. <span role="region" aria-label="Referenced Content"><u>This insightful depiction of a preteen girl encouraged authors who, like Cisneros herself, are Latina to use fictional works to examine experiences from their own youth.</u></span></p>$SATQ$, $SATQ$<p>Which statement, if true, would most strongly support the claim in the underlined sentence?</p>$SATQ$, $SATQ$[{"id":"fef3e067-dc7a-44ed-b6de-d08110114d0c","content":"<p>In interviews, a number of Latina authors say that <em>The House on Mango Street </em>inspired them to write about their own adolescence in their novels.</p>"},{"id":"b4f14f44-0ea1-433e-b1c2-abf938f19665","content":"<p>In published writings, several prominent authors who are not Latina say that reading <em>The House on Mango Street</em> influenced their approach to writing fiction.</p>"},{"id":"cd315f01-e170-4402-86f3-b767d107bed1","content":"<p>The <em>House on Mango Street </em>has sold over six million copies and is one of the most commonly read books among high school and university students in the US.</p>"},{"id":"ee3dee45-3be0-4f20-98d4-4bf81b004a76","content":"<p>Since 1984, new novels about young Latina characters by Latina authors have often been compared to <em>The House on Mango Street</em>.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["fef3e067-dc7a-44ed-b6de-d08110114d0c"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents a finding that, if true, would most strongly support the claim in the underlined sentence. The text begins by explaining that the portrayal of Mexican American culture in Sandra Cisneros&rsquo;s <em>The House on Mango Street</em> inspired later authors to explore their own heritage. Noting that Cisneros&rsquo;s novella was also influential for its depiction of a formative year in a female character&rsquo;s youth, the text then claims that this depiction inspired other Latina authors to use fiction to explore their own experiences of youth. Since this claim addresses how Cisneros encouraged Latina authors specifically to portray their youthful experiences, it would be directly supported by such authors stating that her novella influenced them to write about their own adolescence, or the transitional period between childhood and adulthood. </p><p>Choice B is incorrect. The text states that with its portrayal of Mexican American culture, <em>The House on Mango Street</em> inspired later authors to explore their own heritage, and since this statement isn&rsquo;t limited to only Latina authors, it can be inferred that authors who aren&rsquo;t Latina were also likely influenced by the novella. But because the claim in the underlined sentence concerns the novella&rsquo;s influence on Latina authors specifically, the finding that the book also influenced authors who weren&rsquo;t Latina would fail to provide support for the claim. Choice C is incorrect because the finding that <em>The House on Mango Street</em> has sold millions of copies and is widely read among students in the US doesn&rsquo;t relate directly to the text&rsquo;s claim that the novella has influenced Latina authors specifically. Choice D is incorrect. While comparisons of new novels about young Latina characters by Latina authors to Cisneros&rsquo;s <em>The House on Mango Stree</em>t would likely be founded on similarities between those novels and Cisneros&rsquo;s novella, such similarities wouldn&rsquo;t necessarily be evidence of the novella&rsquo;s influence; such similarities might arise if Cisneros and younger Latina authors alike depicted certain basic cultural and historical features of their communities. Testimony from younger Latina authors about how <em>The House on Mango Street</em> had inspired them would be far more persuasive evidence of the novella&rsquo;s influence.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-336-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$b6036d0f-7a8d-4226-8602-4d1488979bc1$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a13541c0","external_id":"130d0a84-b1b0-4f4b-9201-cd5cc26e4514","vaultid":"832c7c33-4d29-4b2c-b707-09ead941d39e","uId":"2360b7fb-8002-4152-9097-20fed7f006a8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Sandra Cisneros&rsquo;s 1984 novella <em>The House on Mango Street</em> made a lasting impact on US literature. Its depiction of Mexican American culture inspired later authors to examine their own heritage within their fictional works. Also influential was the book&rsquo;s portrayal of the main character, Esperanza, during a pivotal year of her youth. <span role=\"region\" aria-label=\"Referenced Content\"><u>This insightful depiction of a preteen girl encouraged authors who, like Cisneros herself, are Latina to use fictional works to examine experiences from their own youth.</u></span></p>","stem":"<p>Which statement, if true, would most strongly support the claim in the underlined sentence?</p>","answerOptions":[{"id":"fef3e067-dc7a-44ed-b6de-d08110114d0c","content":"<p>In interviews, a number of Latina authors say that <em>The House on Mango Street </em>inspired them to write about their own adolescence in their novels.</p>"},{"id":"b4f14f44-0ea1-433e-b1c2-abf938f19665","content":"<p>In published writings, several prominent authors who are not Latina say that reading <em>The House on Mango Street</em> influenced their approach to writing fiction.</p>"},{"id":"cd315f01-e170-4402-86f3-b767d107bed1","content":"<p>The <em>House on Mango Street </em>has sold over six million copies and is one of the most commonly read books among high school and university students in the US.</p>"},{"id":"ee3dee45-3be0-4f20-98d4-4bf81b004a76","content":"<p>Since 1984, new novels about young Latina characters by Latina authors have often been compared to <em>The House on Mango Street</em>.&nbsp;</p>"}],"keys":["fef3e067-dc7a-44ed-b6de-d08110114d0c"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents a finding that, if true, would most strongly support the claim in the underlined sentence. The text begins by explaining that the portrayal of Mexican American culture in Sandra Cisneros&rsquo;s <em>The House on Mango Street</em> inspired later authors to explore their own heritage. Noting that Cisneros&rsquo;s novella was also influential for its depiction of a formative year in a female character&rsquo;s youth, the text then claims that this depiction inspired other Latina authors to use fiction to explore their own experiences of youth. Since this claim addresses how Cisneros encouraged Latina authors specifically to portray their youthful experiences, it would be directly supported by such authors stating that her novella influenced them to write about their own adolescence, or the transitional period between childhood and adulthood. </p><p>Choice B is incorrect. The text states that with its portrayal of Mexican American culture, <em>The House on Mango Street</em> inspired later authors to explore their own heritage, and since this statement isn&rsquo;t limited to only Latina authors, it can be inferred that authors who aren&rsquo;t Latina were also likely influenced by the novella. But because the claim in the underlined sentence concerns the novella&rsquo;s influence on Latina authors specifically, the finding that the book also influenced authors who weren&rsquo;t Latina would fail to provide support for the claim. Choice C is incorrect because the finding that <em>The House on Mango Street</em> has sold millions of copies and is widely read among students in the US doesn&rsquo;t relate directly to the text&rsquo;s claim that the novella has influenced Latina authors specifically. Choice D is incorrect. While comparisons of new novels about young Latina characters by Latina authors to Cisneros&rsquo;s <em>The House on Mango Stree</em>t would likely be founded on similarities between those novels and Cisneros&rsquo;s novella, such similarities wouldn&rsquo;t necessarily be evidence of the novella&rsquo;s influence; such similarities might arise if Cisneros and younger Latina authors alike depicted certain basic cultural and historical features of their communities. Testimony from younger Latina authors about how <em>The House on Mango Street</em> had inspired them would be far more persuasive evidence of the novella&rsquo;s influence.&nbsp;</p>","parenttemplatename":"OSP-336-TXT","parenttemplateid":"","templateclusterid":"b6036d0f-7a8d-4226-8602-4d1488979bc1","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959336,"updateDate":1691007959336}$SATQ$::jsonb, 1691007959336, 1691007959336),
    ($SATQ$a13c1c66$SATQ$, $SATQ$060fc3ac-31d0-4538-ac31-31f7efc40052$SATQ$::uuid, $SATQ$4af802d6-53bc-483d-838d-c163bfbd0181$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Many animals, including humans, must sleep, and sleep is known to have a role in everything from healing injuries to encoding information in long-term memory. But some scientists claim that, from an evolutionary standpoint, deep sleep for hours at a time leaves an animal so vulnerable that the known benefits of sleeping seem insufficient to explain why it became so widespread in the animal kingdom. These scientists therefore imply that <span aria-hidden="true">______</span><span class="sr-only">blank</span>  </p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"0d562db3-9e7e-4c59-ad59-806901864a9c","content":"<p>prolonged deep sleep is likely advantageous in ways that have yet to be discovered.</p>"},{"id":"ca95bc77-b669-4eb6-b994-87df76074433","content":"<p>most traits perform functions that are hard to understand from an evolutionary standpoint.</p>"},{"id":"5967f156-b7a7-4fbb-92a7-27958c9ab159","content":"<p>it is more important to understand how widespread prolonged deep sleep is than to understand its function.</p>"},{"id":"1fe493cf-358e-4dfd-a318-063ddce80e9c","content":"<p>many traits that provide significant benefits for an animal also likely pose risks to that animal.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["0d562db3-9e7e-4c59-ad59-806901864a9c"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. It most logically completes the text. The text says that some scientists can&rsquo;t explain why prolonged deep sleep is so widespread, given that the known benefits of sleep don&rsquo;t seem to make up for how vulnerable it leaves an animal. This suggests that prolonged deep sleep probably has unknown evolutionary benefits that make up for the vulnerability. &nbsp; &nbsp;</p><p>Choice B is incorrect. It doesn&rsquo;t logically complete the text. The text only discusses the benefits and risks of one trait: sleep. So there&rsquo;s no basis for an inference about &ldquo;most traits.&rdquo; Choice C is incorrect. It doesn&rsquo;t logically complete the text. The text says that it is already known that prolonged deep sleep is widespread in the animal kingdom. Rather, what some scientists can&rsquo;t explain is WHY prolonged deep sleep is so widespread, given that the known benefits of sleep don&rsquo;t seem to make up for how vulnerable it leaves an animal.&nbsp;Choice D is incorrect. It doesn&rsquo;t logically complete the text. The text only discusses the benefits and risks of one trait: sleep. So there&rsquo;s no basis for an inference about &ldquo;many traits.&rdquo; </p>$SATQ$, false, 0, $SATQ$OSP-014-INF$SATQ$, $SATQ$$SATQ$, $SATQ$d40b7225-13f3-4418-8da0-e7a2194e8b4d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a13c1c66","external_id":"060fc3ac-31d0-4538-ac31-31f7efc40052","vaultid":"4af802d6-53bc-483d-838d-c163bfbd0181","uId":"8583ea9b-6e7f-460c-a88b-6fcdb21e2440","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Many animals, including humans, must sleep, and sleep is known to have a role in everything from healing injuries to encoding information in long-term memory. But some scientists claim that, from an evolutionary standpoint, deep sleep for hours at a time leaves an animal so vulnerable that the known benefits of sleeping seem insufficient to explain why it became so widespread in the animal kingdom. These scientists therefore imply that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>  </p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"0d562db3-9e7e-4c59-ad59-806901864a9c","content":"<p>prolonged deep sleep is likely advantageous in ways that have yet to be discovered.</p>"},{"id":"ca95bc77-b669-4eb6-b994-87df76074433","content":"<p>most traits perform functions that are hard to understand from an evolutionary standpoint.</p>"},{"id":"5967f156-b7a7-4fbb-92a7-27958c9ab159","content":"<p>it is more important to understand how widespread prolonged deep sleep is than to understand its function.</p>"},{"id":"1fe493cf-358e-4dfd-a318-063ddce80e9c","content":"<p>many traits that provide significant benefits for an animal also likely pose risks to that animal.</p>"}],"keys":["0d562db3-9e7e-4c59-ad59-806901864a9c"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. It most logically completes the text. The text says that some scientists can&rsquo;t explain why prolonged deep sleep is so widespread, given that the known benefits of sleep don&rsquo;t seem to make up for how vulnerable it leaves an animal. This suggests that prolonged deep sleep probably has unknown evolutionary benefits that make up for the vulnerability. &nbsp; &nbsp;</p><p>Choice B is incorrect. It doesn&rsquo;t logically complete the text. The text only discusses the benefits and risks of one trait: sleep. So there&rsquo;s no basis for an inference about &ldquo;most traits.&rdquo; Choice C is incorrect. It doesn&rsquo;t logically complete the text. The text says that it is already known that prolonged deep sleep is widespread in the animal kingdom. Rather, what some scientists can&rsquo;t explain is WHY prolonged deep sleep is so widespread, given that the known benefits of sleep don&rsquo;t seem to make up for how vulnerable it leaves an animal.&nbsp;Choice D is incorrect. It doesn&rsquo;t logically complete the text. The text only discusses the benefits and risks of one trait: sleep. So there&rsquo;s no basis for an inference about &ldquo;many traits.&rdquo; </p>","parenttemplatename":"OSP-014-INF","parenttemplateid":"","templateclusterid":"d40b7225-13f3-4418-8da0-e7a2194e8b4d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959315,"updateDate":1691007959315}$SATQ$::jsonb, 1691007959315, 1691007959315),
    ($SATQ$a15b3219$SATQ$, $SATQ$40e7dbe5-a37f-471d-bf2a-66c7e950d5d3$SATQ$::uuid, $SATQ$15e49535-f408-4ab3-91fa-66a539975ae0$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<figure class="image"><svg aria-label="Bar graph titled Municipalities’ Responses to Inquiries about Potential Incentives for Firm. The horizontal axis has no label. 3 data categories are shown. The vertical axis is labeled Number of municipalities. It ranges from 0 to 1,300 in increments of 100. Refer to long description." height="578.7376708984375" role="img" viewbox="0 0 400 578.7376708984375" width="400" xmlns="http://www.w3.org/2000/svg"><g data-name="Layer 1" id="ed420550-79eb-48d4-af01-cd27cdd08afd"><defs>
